export function MotionTriggersDemo() {
    const [isHovered, setIsHovered] = useState(false);
    const [isFocused, setIsFocused] = useState(false);
    const [dragX, setDragX] = useState(0);
    // @in-view: IntersectionObserver for entrance animations
    useEffect(() => {
        const els = document.querySelectorAll('[data-motion-inview]');
        const observers = [];
        els.forEach(el => {
            const threshold = parseFloat(el.getAttribute('data-inview-threshold') || '0');
            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 300, easing: 'ease-out', fill: 'both' });
                        observer.disconnect();
                    }
                });
            }, { threshold });
            observer.observe(el);
            observers.push(observer);
        });
        return () => observers.forEach(o => o.disconnect());
    }, []);
    // @scroll: scroll-driven animation progress
    useEffect(() => {
        const els = document.querySelectorAll('[data-motion-scroll]');
        if (!els.length) return;
        function parseScrollTrigger(cfg, el, vh) {
            if (!cfg || typeof cfg !== 'string') return 0;
            const parts = cfg.split(' ');
            if (parts.length < 2) return 0;
            const edge = parts[0];
            const offset = parts[1];
            const elRect = el.getBoundingClientRect();
            let elPos;
            if (edge === 'top') elPos = elRect.top;
            else if (edge === 'center') elPos = elRect.top + elRect.height / 2;
            else if (edge === 'bottom') elPos = elRect.bottom;
            else elPos = elRect.top;
            if (offset.endsWith('%')) {
                return window.scrollY + elPos - vh * (parseFloat(offset) / 100);
            } else if (offset === 'bottom') {
                return window.scrollY + elPos - vh;
            } else if (offset === 'top') {
                return window.scrollY + elPos;
            }
            return window.scrollY + elPos - vh * 0.5;
        }
        function computeProgress(el) {
            const rect = el.getBoundingClientRect();
            const vh = window.innerHeight;
            const startCfg = el.getAttribute('data-scroll-start') || 'top 80%';
            const endCfg = el.getAttribute('data-scroll-end') || 'bottom 20%';
            const startPos = parseScrollTrigger(startCfg, el, vh);
            const endPos = parseScrollTrigger(endCfg, el, vh);
            const raw = (window.scrollY - startPos) / (endPos - startPos);
            return Math.max(0, Math.min(1, raw));
        }
        function scrubValue(el, target) {
            const delay = parseFloat(el.getAttribute('data-scroll-scrub') || '0');
            if (delay > 0) {
                return (scrubCache.get(el) || 0) + (target - (scrubCache.get(el) || 0)) * Math.min(1, 16.67 / (delay * 1000));
            }
            return target;
        }
        const scrubCache = new Map();
        const handleScroll = () => {
            els.forEach(el => {
                const target = computeProgress(el);
                const scrubbed = scrubValue(el, target);
                scrubCache.set(el, scrubbed);
                const anims = el.getAnimations();
                anims.forEach(a => {
                    const duration = a.effect?.getTiming()?.duration || 300;
                    a.currentTime = scrubbed * duration;
                });
            });
        };
        window.addEventListener('scroll', handleScroll, { passive: true });
        handleScroll();
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);
    // @drag-horizontal / @drag-vertical: gesture-driven animation progress
    useEffect(() => {
        const els = document.querySelectorAll('[data-motion-drag]');
        if (!els.length) return;

        function parseConstraint(cfg) {
            if (!cfg) return { min: -Infinity, max: Infinity };
            if (cfg === 'parent') {
                const parent = el.parentElement;
                if (!parent) return { min: -Infinity, max: Infinity };
                const elRect = el.getBoundingClientRect();
                const parentRect = parent.getBoundingClientRect();
                return { min: 0, max: parentRect.width - elRect.width };
            }
            const parts = cfg.split(' ');
            let min = -Infinity, max = Infinity;
            parts.forEach(p => {
                const [key, val] = p.split(':');
                if (key === 'left' || key === 'top') min = parseFloat(val) || 0;
                if (key === 'right' || key === 'bottom') max = parseFloat(val) || Infinity;
            });
            return { min, max };
        }

        els.forEach(el => {
            const axis = el.getAttribute('data-motion-drag') || 'x';
            const constraints = el.getAttribute('data-drag-constraints') || '';
            const elastic = parseFloat(el.getAttribute('data-drag-elastic') || '0');
            const threshold = parseFloat(el.getAttribute('data-drag-threshold') || '0');
            const velocityMax = parseFloat(el.getAttribute('data-drag-velocity-max') || '2000');
            const constraint = parseConstraint(constraints);
            const maxExtent = Math.abs(constraint.max - constraint.min) || 1;
            let startPos = 0, currentDelta = 0, isDragging = false;
            let lastMoveTime = 0, lastMovePos = 0, velocity = 0;

            const onPointerDown = (e) => {
                isDragging = true;
                startPos = axis === 'x' ? e.clientX : e.clientY;
                currentDelta = 0;
                el.setPointerCapture(e.pointerId);
            };

            const onPointerMove = (e) => {
                if (!isDragging) return;
                const now = performance.now();
                const raw = (axis === 'x' ? e.clientX : e.clientY) - startPos;
                if (lastMoveTime > 0) {
                    const dt = now - lastMoveTime;
                    const dp = Math.abs(raw - lastMovePos);
                    if (dt > 0) velocity = Math.min(velocityMax, dp / dt * 1000);
                }
                lastMoveTime = now;
                lastMovePos = raw;
                let constrained = raw;
                if (raw < constraint.min) {
                    constrained = constraint.min - (constraint.min - raw) * (1 - elastic);
                } else if (raw > constraint.max) {
                    constrained = constraint.max + (raw - constraint.max) * (1 - elastic);
                }
                currentDelta = raw;
                const progress = Math.min(1, Math.abs(constrained) / maxExtent);
                const anims = el.getAnimations();
                anims.forEach(a => {
                    const duration = a.effect?.getTiming()?.duration || 300;
                    a.currentTime = progress * duration;
                });
            };

            const onPointerUp = (e) => {
                isDragging = false;
                el.releasePointerCapture(e.pointerId);
                const progress = Math.abs(currentDelta) / maxExtent;
                if (progress >= threshold && maxExtent > 0) {
                    const anims = el.getAnimations();
                    anims.forEach(a => a.play());
                } else {
                    const anims = el.getAnimations();
                    anims.forEach(a => a.reverse());
                }
            };

            el.addEventListener('pointerdown', onPointerDown);
            el.addEventListener('pointermove', onPointerMove);
            el.addEventListener('pointerup', onPointerUp);
            el.addEventListener('pointercancel', onPointerUp);

            // Cleanup
            el._dragCleanup = () => {
                el.removeEventListener('pointerdown', onPointerDown);
                el.removeEventListener('pointermove', onPointerMove);
                el.removeEventListener('pointerup', onPointerUp);
                el.removeEventListener('pointercancel', onPointerUp);
            };
        });

        return () => {
            els.forEach(el => {
                if (el._dragCleanup) el._dragCleanup();
            });
        };
    }, []);

    return (
        <div
            className={styles['container']}
        >
            <h3
                className={styles['title']}
            >
                {'Motion Triggers Demo'}
            </h3>
            <p
                className={styles['subtitle']}
            >
                {' ·  ·  ·  ·  · @drag'}
            </p>
            <div
                className={styles['card']}
            >
                <h4
                    className={styles['label']}
                >
                    {' 触发器'}
                </h4>
                <button
                    className={styles['btn-hover']}
                    onMouseEnter={(e) => { e.currentTarget.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 300, easing: 'ease-out' }); }}
                    onMouseLeave={(e) => { e.currentTarget.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 300, easing: 'ease-out' }); }}
                >
                    {'Hover then leave'}
                </button>
            </div>
            <div
                className={styles['card']}
            >
                <h4
                    className={styles['label']}
                >
                    {' 触发器'}
                </h4>
                <input
                    placeholder="Focus me"
                    className={styles['input-focus']}
                    onFocus={(e) => { e.currentTarget.animate([{ boxShadow: '0 0 0 0 rgba(59,130,246,0)' }, { boxShadow: '0 0 0 3px rgba(59,130,246,0.5)' }], { duration: 200, easing: 'ease-out', fill: 'both' }); }}
                    onBlur={(e) => { e.currentTarget.animate([{ boxShadow: '0 0 0 3px rgba(59,130,246,0.5)' }, { boxShadow: '0 0 0 0 rgba(59,130,246,0)' }], { duration: 200, easing: 'ease-out', fill: 'both' }); }}
                />
            </div>
            <div
                className={styles['card']}
            >
                <h4
                    className={styles['label']}
                >
                    {' 触发器（持续循环）'}
                </h4>
                <div
                    className={styles['spin-box']}
                >
                    <p>
                        {'↻'}
                    </p>
                </div>
            </div>
            <div
                className={styles['card']}
            >
                <h4
                    className={styles['label']}
                >
                    {' 触发器 + 子属性'}
                </h4>
                <div
                    data-motion-inview="true"
                    data-inview-threshold="0"
                >
                    <p>
                        {'Slide in once'}
                    </p>
                </div>
                <div
                    data-motion-inview="true"
                    data-inview-threshold="0.5"
                >
                    <p>
                        {'Slide in repeat (threshold 0.5)'}
                    </p>
                </div>
            </div>
            <div
                className={styles['card']}
            >
                <h4
                    className={styles['label']}
                >
                    {' 触发器 + scroll-start/end/scrub'}
                </h4>
                <div
                    className={styles['scroll-area']}
                    data-motion-scroll="true"
                    data-scroll-start="top 80%"
                    data-scroll-end="bottom 20%"
                    data-scroll-scrub="0.5"
                >
                    <p>
                        {'Scroll to animate'}
                    </p>
                </div>
            </div>
            <div
                className={styles['card']}
            >
                <h4
                    className={styles['label']}
                >
                    {'@dragHorizontal / @dragVertical 拖拽'}
                </h4>
                <div
                    className={styles['drag-box']}
                    data-motion-drag="x"
                    data-drag-constraints="left:0 right:300"
                    data-drag-elastic="0.2"
                    data-drag-threshold="30"
                    data-drag-velocity-max="2000"
                >
                    <p>
                        {'Drag me →'}
                    </p>
                </div>
                <div
                    className={styles['drag-box-vertical']}
                    data-motion-drag="y"
                    data-drag-constraints="top:0 bottom:200"
                    data-drag-elastic="0.3"
                    data-drag-threshold="0"
                    data-drag-velocity-max="2000"
                >
                    <p>
                        {'Drag me ↓'}
                    </p>
                </div>
            </div>
        </div>
    );
}

